"""
Module 6: Educational Risk Prediction Interface
-----------------------------------------------
Runs inference on user-entered clinical attributes and produces:
  - Estimated risk tier (Low / Moderate / Elevated Risk)
  - Calibrated model probability
  - Contributing clinical factors
  - Mandatory educational disclaimer
"""

from typing import Any
import pandas as pd

EDUCATIONAL_DISCLAIMER = (
    "EDUCATIONAL PROTOTYPE DISCLAIMER: This prediction is generated by a student "
    "machine learning model trained on demonstration/synthetic data. It is NOT a "
    "medical diagnosis, screening test, or clinical recommendation. Always consult "
    "a qualified physician for medical evaluation."
)


def predict_patient_risk(
    model_eval,
    patient_input: dict[str, Any],
) -> dict[str, Any]:
    """Predict risk tier and probability for a single patient record."""
    input_df = pd.DataFrame([patient_input])
    prob_elevated = float(model_eval.pipeline.predict_proba(input_df)[0, 1])

    if prob_elevated < 0.30:
        risk_tier = "Low Estimated Risk"
    elif prob_elevated < 0.65:
        risk_tier = "Moderate Estimated Risk"
    else:
        risk_tier = "Elevated Estimated Risk"

    return {
        "model_used": model_eval.name,
        "probability_pct": round(prob_elevated * 100.0, 1),
        "risk_tier": risk_tier,
        "top_features": model_eval.feature_importances.head(5),
        "disclaimer": EDUCATIONAL_DISCLAIMER,
    }
